<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('payments.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';require __DIR__.'/purchase_helpers.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$customerId=(int)$_POST['customer_id'];$targetSaleId=(int)($_POST['target_sale_id']??0);$amount=(float)$_POST['amount'];$db->beginTransaction();try{if($amount<=0)throw new RuntimeException('Enter the amount received.');$c=$db->prepare('SELECT * FROM customers WHERE id=? FOR UPDATE');$c->execute([$customerId]);$customer=$c->fetch();if(!$customer)throw new RuntimeException('Choose a customer.');$targetSale=null;if($targetSaleId){$t=$db->prepare('SELECT * FROM sales WHERE id=? AND customer_id=? AND payment_type="credit" AND status NOT IN("cancelled","returned") FOR UPDATE');$t->execute([$targetSaleId,$customerId]);$targetSale=$t->fetch();if(!$targetSale)throw new RuntimeException('The selected credit invoice was not found.');if((float)$targetSale['balance']<=0)throw new RuntimeException('This invoice is already fully paid.');if($amount>(float)$targetSale['balance'])throw new RuntimeException('Payment cannot be more than this invoice balance of '.money($targetSale['balance']).'.');}$receipt=next_number($db,'customer_payments','REC');$allocationMode=$targetSaleId?'single':'oldest';$db->prepare('INSERT INTO customer_payments(receipt_no,customer_id,payment_date,amount,method,reference_no,allocation_mode,notes,collected_by) VALUES(?,?,NOW(),?,?,?,?,?,?)')->execute([$receipt,$customerId,$amount,$_POST['method'],trim($_POST['reference_no']),$allocationMode,trim($_POST['notes']),user()['id']]);$paymentId=(int)$db->lastInsertId();$remaining=$amount;if($targetSale){$bills=[$targetSale];}else{$billStmt=$db->prepare('SELECT * FROM sales WHERE customer_id=? AND balance>0 AND status IN("unpaid","partially_paid","overdue") ORDER BY due_date IS NULL,due_date,sale_date,id FOR UPDATE');$billStmt->execute([$customerId]);$bills=$billStmt->fetchAll();}foreach($bills as $bill){if($remaining<=0)break;$invoiceApplied=min($remaining,(float)$bill['balance']);$newBalance=(float)$bill['balance']-$invoiceApplied;$db->prepare('INSERT INTO customer_payment_allocations(payment_id,sale_id,amount) VALUES(?,?,?)')->execute([$paymentId,$bill['id'],$invoiceApplied]);$db->prepare('UPDATE sales SET paid_amount=paid_amount+?,balance=?,status=? WHERE id=?')->execute([$invoiceApplied,$newBalance,$newBalance<=0?'paid':'partially_paid',$bill['id']]);$remaining-=$invoiceApplied;}$invoiceAllocated=$amount-$remaining;$accountApplied=min($amount,max(0,(float)$customer['outstanding']));$advance=$amount-$accountApplied;$db->prepare('UPDATE customers SET outstanding=GREATEST(0,outstanding-?),total_payments=total_payments+?,last_payment_at=NOW() WHERE id=?')->execute([$accountApplied,$amount,$customerId]);audit($db,'create','customer_payment',$paymentId,null,['receipt_no'=>$receipt,'amount'=>$amount,'target_sale_id'=>$targetSaleId?:null,'account_balance_reduced'=>$accountApplied,'invoice_allocated'=>$invoiceAllocated,'advance'=>$advance]);$db->commit();flash('success',"Payment $receipt saved. Invoice and customer balance updated.");redirect($targetSaleId?'sale_view.php?id='.$targetSaleId:'payments.php');}catch(Throwable $e){$db->rollBack();flash('danger',$e->getMessage());redirect($targetSaleId?'payments.php?customer_id='.$customerId.'&sale_id='.$targetSaleId.'#receive-payment':'payments.php');}}
$q=trim($_GET['q']??'');$selectedId=(int)($_GET['customer_id']??0);$selectedSaleId=(int)($_GET['sale_id']??0);$selectedSale=null;if($selectedSaleId){$ss=$db->prepare('SELECT id,sale_no,customer_id,total,paid_amount,balance,status FROM sales WHERE id=? AND payment_type="credit"');$ss->execute([$selectedSaleId]);$selectedSale=$ss->fetch();if($selectedSale){$selectedId=(int)$selectedSale['customer_id'];}else{$selectedSaleId=0;}}$customers=$db->query('SELECT * FROM customers WHERE status="active" AND (credit_enabled=1 OR outstanding>0) ORDER BY name')->fetchAll();$sql='SELECT c.*,(SELECT COUNT(*) FROM sales s WHERE s.customer_id=c.id AND s.balance>0 AND s.status NOT IN("cancelled","returned")) open_bills,(SELECT COALESCE(SUM(s.balance),0) FROM sales s WHERE s.customer_id=c.id AND s.balance>0 AND s.due_date<CURDATE() AND s.status NOT IN("cancelled","returned")) overdue_amount,(SELECT MAX(p.payment_date) FROM customer_payments p WHERE p.customer_id=c.id) recent_payment_date FROM customers c WHERE c.status="active" AND (c.credit_enabled=1 OR c.outstanding>0)';$args=[];if($q!==''){$sql.=' AND (c.name LIKE ? OR c.customer_code LIKE ? OR c.phone LIKE ? OR c.business_name LIKE ?)';$like='%'.$q.'%';$args=[$like,$like,$like,$like];}$sql.=' ORDER BY c.outstanding DESC,c.name';$st=$db->prepare($sql);$st->execute($args);$balances=$st->fetchAll();$rows=$db->query('SELECT p.*,c.name customer FROM customer_payments p JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC LIMIT 30')->fetchAll();$totalOutstanding=array_sum(array_map(fn($r)=>(float)$r['outstanding'],$balances));$totalOverdue=array_sum(array_map(fn($r)=>(float)$r['overdue_amount'],$balances));page_start('Credit Collections','payments.php');?>
<section class="action-banner"><div><span class="step-number">1</span><div><b>See and collect all customer credit balances here</b><p>Search a customer, view their full account, or select Receive Payment. The live balance updates as soon as a receipt is saved.</p></div></div></section>
<section class="kpi-grid collection-kpis"><article class="kpi"><span>Customers Owing</span><strong><?=count(array_filter($balances,fn($r)=>(float)$r['outstanding']>0))?></strong></article><article class="kpi"><span>Total Credit to Collect</span><strong><?=money($totalOutstanding)?></strong></article><article class="kpi overdue-kpi"><span>Overdue Invoices</span><strong><?=money($totalOverdue)?></strong></article></section>
<div class="collection-tabs"><button class="active" data-collection-tab="balances">All Credit Balances</button><button data-collection-tab="receipts">Recent Payment Receipts</button></div>
<div class="page-grid collections-layout"><section class="panel table-panel collection-section active" id="balances"><div class="panel-head"><div><span class="eyebrow">Money to collect</span><h3>All customer credit balances</h3></div><form class="balance-search"><input name="q" value="<?=e($q)?>" placeholder="Search name, phone or code"><button class="btn secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th class="right">Open Bills</th><th class="right">Overdue</th><th class="right">Credit Balance</th><th>Last Payment</th><th>Actions</th></tr></thead><tbody><?php if(!$balances):?><tr><td colspan="7"><div class="empty-state compact"><b>No credit customers found</b></div></td></tr><?php endif;?><?php foreach($balances as $r):?><tr><td><b><?=e($r['name'])?></b><br><span class="muted"><?=e($r['customer_code'])?></span></td><td><?=e($r['phone']?:'—')?></td><td class="right"><?=(int)$r['open_bills']?></td><td class="right"><span class="status <?=((float)$r['overdue_amount']>0)?'status-unpaid':'status-paid'?>"><?=money($r['overdue_amount'])?></span></td><td class="right"><b class="credit-balance"><?=money($r['outstanding'])?></b></td><td><?=$r['recent_payment_date']?date('d M Y',strtotime($r['recent_payment_date'])):'—'?></td><td class="collection-actions"><a href="customer_view.php?id=<?=$r['id']?>">View Account</a><?php if((float)$r['outstanding']>0):?><a class="btn tiny primary" href="payments.php?customer_id=<?=$r['id']?>#receive-payment">Receive Payment</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel table-panel collection-section" id="receipts"><div class="panel-head"><div><span class="eyebrow">Money received</span><h3>Recent payment receipts</h3></div></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Date</th><th>Method</th><th class="right">Amount</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="empty-state compact"><b>No receipts yet</b></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['receipt_no'])?></b><br><a class="row-edit" href="edit_record.php?type=customer_payment&id=<?=$r['id']?>">Correct</a></td><td><?=e($r['customer'])?></td><td><?=date('d M Y, H:i',strtotime($r['payment_date']))?></td><td><span class="tag"><?=e(str_replace('_',' ',$r['method']))?></span></td><td class="right"><b><?=money($r['amount'])?></b></td></tr><?php endforeach;?></tbody></table></div></section>
<aside class="panel receive-panel" id="receive-payment"><div class="panel-head"><div><span class="eyebrow">New receipt</span><h3>Receive credit payment</h3></div></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf()?>"><label class="full">Customer<select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=$selectedId===(int)$c['id']?'selected':''?>><?=e($c['name'])?> — owes <?=money($c['outstanding'])?></option><?php endforeach;?></select></label><label class="full">Amount received<input type="number" name="amount" min=".01" step=".01" required></label><label>Received using<select name="method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option></select></label><label>Reference<input name="reference_no"></label><label class="full">Notes<textarea name="notes" rows="2"></textarea></label><div class="plain-help full">The customer balance reduces immediately. Open invoices are paid from the oldest due invoice first.</div><button class="btn primary full">Save Payment & Receipt</button></form></aside></div>
<?php if($selectedSale):?><script>document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('#receive-payment form'),head=document.querySelector('#receive-payment .panel-head'),amount=form?.querySelector('[name="amount"]'),help=form?.querySelector('.plain-help');if(!form)return;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='target_sale_id';hidden.value=<?=json_encode($selectedSaleId)?>;form.appendChild(hidden);if(amount){amount.max=<?=json_encode((float)$selectedSale['balance'])?>;amount.placeholder='Maximum <?=e(money($selectedSale['balance']))?>'}if(help)help.innerHTML='<b>Selected invoice: <?=e($selectedSale['sale_no'])?></b><br>This payment updates this invoice only. Maximum due: <?=e(money($selectedSale['balance']))?>.';if(head){const note=document.createElement('div');note.className='selected-invoice';note.innerHTML='<span>Invoice selected</span><b><?=e($selectedSale['sale_no'])?></b><strong>Due <?=e(money($selectedSale['balance']))?></strong>';head.after(note)}});</script><?php endif;?>
<style>.collection-kpis{margin:18px 0}.overdue-kpi{border-top:4px solid #d14b43}.collection-tabs{display:flex;gap:8px;margin:0 0 12px}.collection-tabs button{border:1px solid #dfe5df;background:#fff;padding:11px 16px;border-radius:9px;font-weight:700}.collection-tabs button.active{background:#174e39;color:#fff}.collection-section{display:none}.collection-section.active{display:block}.collections-layout{align-items:start}.balance-search{display:flex;gap:8px;max-width:420px}.balance-search input{min-width:240px}.collection-actions{display:flex;align-items:center;gap:10px;white-space:nowrap}.btn.tiny{padding:7px 10px;font-size:12px}.credit-balance{color:#b23a34}.receive-panel{position:sticky;top:18px}@media(max-width:900px){.receive-panel{position:static}.balance-search{max-width:none}.panel-head{align-items:flex-start;gap:12px}.collection-actions{white-space:normal;flex-wrap:wrap}}@media(max-width:600px){.balance-search{width:100%;flex-direction:column}.balance-search input{min-width:0}.collection-tabs{overflow:auto}}</style><script>document.querySelectorAll('[data-collection-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-collection-tab]').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.collection-section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#'+b.dataset.collectionTab).classList.add('active')});<?php if($selectedId):?>document.querySelector('#receive-payment').scrollIntoView({behavior:'smooth',block:'start'});<?php endif;?></script><?php page_end();
